class Handover implements ConsumerRebalanceListener {
    private final Consumer<String, String> consumer;
    private final Map<TopicPartition, Long> done = new HashMap<>();   // next offset to read, per partition

    Handover(Consumer<String, String> consumer) { this.consumer = consumer; }

    void processed(ConsumerRecord<String, String> r) {
        done.put(new TopicPartition(r.topic(), r.partition()), r.offset() + 1);
    }

    @Override public void onPartitionsRevoked(Collection<TopicPartition> partitions) {
        Map<TopicPartition, OffsetAndMetadata> offsets = new HashMap<>();
        for (TopicPartition tp : partitions) {
            Long next = done.remove(tp);
            if (next != null) offsets.put(tp, new OffsetAndMetadata(next));
        }
        if (!offsets.isEmpty()) consumer.commitSync(offsets);
    }

    @Override public void onPartitionsAssigned(Collection<TopicPartition> partitions) { }

    @Override public void onPartitionsLost(Collection<TopicPartition> partitions) {
        partitions.forEach(done::remove);                             // never commit a lost partition
    }
}

